    /// <param name="response">Response produced by <see cref="CreateUserEndpoint.Handle"/>.</param>
    /// <param name="expectedType">Expected problem type URI.</param>
    /// <param name="expectedTitle">Expected problem title.</param>
    private static void AssertProblem(EndpointResponse response, string expectedType, string expectedTitle)
    {
        Assert.Equal(HttpStatus.BadRequest, response.StatusCode);
        Assert.Null(response.User);
        Assert.NotNull(response.Problem);
        Assert.Equal(expectedType, response.Problem.Type);
        Assert.Equal(expectedTitle, response.Problem.Title);
        Assert.Equal(HttpStatus.BadRequest, response.Problem.Status);
    }
}
